		{ "GameFontScale", new[] { "게임 안 모든 글자 크기(%, 메뉴·버튼·수치·대사 모두 키움, Steam Deck 같은 작은 화면용. 너무 크면 일부 글자가 칸 밖으로 넘칩니다). 100=원래대로, 120=20% 크게.", "ゲーム内のすべての文字サイズ（%、メニュー・ボタン・数値・会話をすべて拡大、Steam Deck などの小さい画面向け。大きくしすぎると枠からはみ出す文字があります）。100=通常、120=2 割大きく。" } },
		{ "UiLanguage", new[] { "이 모드 화면의 언어: 게임 언어에 맞춤 / 간체 중국어 / 번체 중국어 / 한국어 / 일본어 / 영어.", "この MOD の画面の言語：ゲームに合わせる／簡体字／繁体字／韓国語／日本語。" } },
		{ "PanelTheme", new[] { "커피 동반자 창의 색상: 밝게(기본) / 어둡게(먹색 바탕) / 시스템 설정에 맞춤(Windows 앱 모드).", "珈琲のおともウィンドウの配色：ライト（既定）／ダーク（墨色の背景）／システムに合わせる（Windows のアプリモード）。" } },
		{ "PanelFont", new[] { "이 모드 화면의 글꼴: 원본 명조체(게임 대사 글꼴, 기본) / 시스템 글꼴.", "この MOD の画面のフォント：源ノ明朝（ゲームの会話のフォント、既定）／システムフォント。" } },
